        >
          <Role role="quote">
            {lines.map((line, i) => {
              const t = interpolate(frame - 36 - i * 11, [0, 30], [0, 1], {...clamp, easing: easeOut});
              return (
                <div key={i} style={{overflow: 'hidden', paddingBottom: size * 0.08, marginBottom: -size * 0.08}}>
